			id := path[len("/accounts/"):]
			for _, account := range accounts {
				if account.ID == id {
					writeJSON(w, account)
					return
				}
			}
			http.NotFound(w, r)
		}
	})

	return &http.Server{
		Addr:                addr,
		Handler:             handler,
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
		MaxHeaderValueCount: 100,
	}
}

func accountsForQuery(accounts []Account, rawQuery string) ([]Account, bool) {
	query, err := url.ParseQuery(rawQuery)
	filtered := make([]Account, 0, len(accounts))
	values := query["active"]
	if err != nil || len(values) > 1 ||
		(len(values) == 1 && values[0] != "true" && values[0] != "false") {
		return nil, false
	}
	if len(values) == 0 {
		return append(filtered, accounts...), true
	}

	active := values[0] == "true"
	for _, account := range accounts {
		if account.Active == active {
			filtered = append(filtered, account)
		}
	}
	return filtered, true
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(value)
}

