		{name: "filtered list", method: http.MethodGet, path: "/accounts?active=false", status: http.StatusOK, contentType: "application/json", body: "[{\"id\":\"b\",\"name\":\"Beta\",\"cents\":200,\"active\":false}]\n"},
		{name: "account", method: http.MethodGet, path: "/accounts/a", status: http.StatusOK, contentType: "application/json", body: "{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}\n"},
		{name: "unknown path", method: http.MethodGet, path: "/other", status: http.StatusNotFound, contentType: "text/plain; charset=utf-8", body: "404 page not found\n"},
