			}
			if recorder.Header().Get("Content-Type") != test.contentType {
				t.Errorf("NewServer(%q).ServeHTTP Content-Type = %q, want %q", test.path, recorder.Header().Get("Content-Type"), test.contentType)
			}
			if recorder.Body.String() != test.body {
